import DialogContent from '@mui/material/DialogContent';
import Typography from '@mui/material/Typography';
import themes from '../../Burger/theme';
import { useThemeContext } from '../../Burger/themeContext';
import Link from '@mui/material/Link';
import React from 'react';
import modelisation from './../../../img/couverture.png';
import demoPorte from './../../../img/demo_porte.png';
import Box from '@mui/material/Box';
import { useTranslation } from 'react-i18next';

export function Math(){
    const {darkMode} = useThemeContext();
    const { t } = useTranslation();

    return(
        <>
        <DialogContent dividers sx={{bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor}}>
          <Box sx={{ display: 'flex', justifyContent: 'center', marginBottom: '20px' }}>
            <img
              width='50%'
              src={modelisation}
              alt='alt'
              loading="lazy"
            />
          </Box>
          <Typography gutterBottom>
          {t('MATH_PROJECT_INTRO')}
          </Typography>
          <Typography gutterBottom>
          {t('MATH_PROJECT_DESCRIPTION_1')}
          </Typography>
          <Typography gutterBottom>
          {t('MATH_PROJECT_DESCRIPTION_2')}
          </Typography>
          <Typography gutterBottom>
          {t('MATH_PROJECT_DESCRIPTION_3')}
          </Typography>
          <Box sx={{ display: 'flex', justifyContent: 'center', marginBottom: '20px' }}>
            <img
              width='70%'
              src={demoPorte}
              alt='alt'
              loading="lazy"
            />
          </Box>
          <Typography gutterBottom>
          {t('MATH_PROJECT_CONCLUSION')}
          </Typography>
        </DialogContent>
        </>
    )
}