import React from 'react';
import Box from '@mui/material/Box';
import AspectRatio from '@mui/joy/AspectRatio';
import Card from '@mui/joy/Card';
import CardContent from '@mui/joy/CardContent';
import CardOverflow from '@mui/joy/CardOverflow';
import Divider from '@mui/joy/Divider';
import Typography from '@mui/joy/Typography';
import { useThemeContext } from './../Burger/themeContext';
import themes from './../Burger/theme';
import STMicroelectronics from './../../img/ST.png';
import Harvest from './../../img/Harvest.JPG'
import { DarkMode } from '@mui/icons-material';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogActions from '@mui/material/DialogActions';
import IconButton from '@mui/material/IconButton';
import CloseIcon from '@mui/icons-material/Close';
import { styled } from '@mui/material/styles';
import List from '@mui/material/List';
import Button from '@mui/material/Button';
import { useTranslation } from 'react-i18next';
import harvestdecor from './../../img/harvestdecor.jpg';
import STdecor from './../../img/STdecor.jpg';
import CardCover from '@mui/joy/CardCover';
import LocationOnRoundedIcon from '@mui/icons-material/LocationOnRounded';

const BootstrapDialog = styled(Dialog)(({ theme }) => ({
  '& .MuiDialog-paper': {
    backgroundColor: 'white', // Couleur de fond de la pop-up
    maxWidth: '60%',
  },
  '& .MuiDialogContent-root': {
    padding: theme.spacing(2),
    display: 'flex',
    flexWrap: 'wrap',
    justifyContent: 'center',
  },
  '& .MuiDialogActions-root': {
    padding: theme.spacing(1),
  },
}));

function About() {
  const {darkMode} = useThemeContext();
  const [openST, setOpenST] = React.useState(false);
  const [openHarvest, setOpenHarvest] = React.useState(false)
  const { t } = useTranslation();

  const handleClickOpenST = () => {
    setOpenST(true);
  };
  const handleCloseST = () => {
    setOpenST(false);
  };

  const handleClickOpenHarvest = () => {
    setOpenHarvest(true);
  };
  const handleCloseHarvest = () => {
    setOpenHarvest(false);
  };

  return (
    <Box
      component="main"
      sx={{
        flexGrow: 1,
        p: 5,
        minHeight: '100vh',
        backgroundColor: darkMode? themes.dark.backgroundColor : themes.light.backgroundColor,
      }}
    >      
    <Box sx={{ margin: '2%', textAlign: 'center'}}>
        <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '2.5rem', marginBottom: '3%'}}>{t('EXPERIENCE')}</Typography><br></br>

        <Box style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'space-evenly', textAlign: 'left' }}>
        <Card variant="outlined" onClick={handleClickOpenST} sx={{ width: 400, height: '20%', margin: '20px',
            borderRadius: 3,
            transition: '0.2s',
            '&:hover': { transform: 'scale(1.05)' }, bgcolor: darkMode? themes.dark.backgroundColor : themes.light.backgroundColor}}>
      <CardOverflow >
        <AspectRatio ratio="2">
        <img src={STMicroelectronics} alt="STMicroelectronics" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        </AspectRatio>
      </CardOverflow>
      <CardContent>
        <Typography level="title-lg" sx={{color: darkMode? themes.dark.text : themes.light.textColor}}>{t('STCARDTITLE')}</Typography><br/>
        <Typography level="title-md" sx={{color: darkMode? themes.dark.text : themes.light.textColor}}>{t('STCARDCONTENT')}</Typography><br/>
        <Divider inset="context" />
        <Typography level="body-sm" sx={{color: darkMode? themes.dark.primaryColor : themes.light.primaryColor}}>2023 - 2024</Typography>
      </CardContent>
    </Card>


    <Card variant="outlined" onClick={handleClickOpenHarvest} sx={{ width: 400, height:'20%', margin: '20px',
            borderRadius: 3,
            transition: '0.2s',
            '&:hover': { transform: 'scale(1.05)' }, bgcolor: darkMode? themes.dark.backgroundColor : themes.light.backgroundColor}}>
      <CardOverflow>
        <AspectRatio ratio="2">
        <img src={Harvest} alt="STMicroelectronics" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        </AspectRatio>
      </CardOverflow>
      <CardContent>
        <Typography level="title-lg" sx={{color: darkMode? themes.dark.text : themes.light.textColor}}>{t('HARVESTCARDTITLE')}</Typography><br/>
        <Typography level="title-md" sx={{color: darkMode? themes.dark.text : themes.light.textColor}}>{t('HARVESTCARDCONTENT')}</Typography><br/>
        <Divider inset="context" />
        <Typography level="body-sm" sx={{color: darkMode? themes.dark.primaryColor : themes.light.primaryColor}}>07/05/2023 - 07/07/2023</Typography>
      </CardContent>

    </Card>
      <BootstrapDialog
      onClose={handleCloseST}
      aria-labelledby="customized-dialog-title"
      open={openST}
    >
      <DialogTitle sx={{ textAlign: 'center', m: 0, p: 2, bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor, fontSize: '2.5rem' }} id="customized-dialog-title">
        STMicroelectronics
      </DialogTitle>
      <IconButton
        aria-label="close"
        onClick={handleCloseST}
        sx={{
          position: 'absolute',
          right: 8,
          top: 8,
          color: (theme) => theme.palette.grey[500],
        }}
      >
        <CloseIcon />
      </IconButton>
      <DialogContent dividers sx={{bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, display: 'flex', flexDirection: { xs: 'column', md: 'row' }, gap: 4}}>
      <Card sx={{width: '100%', maxWidth: 500, minHeight: 300, margin: { xs: '0 auto', lg: '0 20px 0 0' }, margin: '0 auto 20px', boxShadow: 'none', '@media (min-width:1665px)': {
        width: '45%',
      } }}>
      <CardCover>
        <img
          src={STdecor}
          alt="STMicroelectronics"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
      <CardCover
        sx={{
          background:
            'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 100px), linear-gradient(to top, rgba(0,0,0,0.8), rgba(0,0,0,0) 200px)',
        }}
      />
      <CardContent sx={{ justifyContent: 'flex-end', p: 2 }}>
        <Typography level="title-lg" textColor="#fff" mb={1} sx={{ textShadow: '0 2px 4px rgba(0,0,0,0.5)' }}>
          STMicroelectronics
        </Typography>
        <Typography
          startDecorator={<LocationOnRoundedIcon sx={{ fontSize: '16px' }} />}
          textColor="neutral.300"
          fontSize="sm"
        >
          Sophia Antipolis, France
        </Typography>
      </CardContent>
    </Card>
    <Box sx={{
      width: '100%',
      maxWidth: 800,
      marginTop: { xs: 2, lg: 0 },
      // Même logique pour le texte
      '@media (min-width:1665px)': {
        width: '45%',
      },
    }}>
        <Typography gutterBottom sx={{color: darkMode ? themes.dark.text : themes.light.textColor, marginTop: '2%'}}>
          {t('ABOUT_ST_DESCRIPTION_1')}
        </Typography><br></br>
        <Typography gutterBottom sx={{color: darkMode ? themes.dark.text : themes.light.textColor}}>
          {t('ABOUT_ST_DESCRIPTION_2')}
        </Typography><br></br>
        <Typography gutterBottom sx={{color: darkMode ? themes.dark.text : themes.light.textColor}}>
          {t('ABOUT_ST_DESCRIPTION_3')}
        </Typography><br></br>
        <Typography gutterBottom sx={{color: darkMode ? themes.dark.text : themes.light.textColor, marginBottom: '2%'}}>
        Ayant entamé le développement de cette application from scratch (à partir de zéro) mes principales missions sont l’implémentation des fonctionnalités essentielles pour obtenir une première version du produit. A cet effet, j’ai réalisé plusieurs opérations CRUD (opérations de création, d’affichage, de modification et de suppression de données) qui m’ont permis de bien comprendre le rôle de chaque couche de l’architecture : l’application, le domain et l’infrastructure. De plus, les données ciblées par les opérations CRUD se trouvant sur un repo GitHub distant, j’ai été amenée à utiliser l’interface Simple Git avec le pattern Unit of Work.
        </Typography>
        </Box>
      </DialogContent>
    </BootstrapDialog>
    <BootstrapDialog
      onClose={handleCloseHarvest}
      aria-labelledby="customized-dialog-title"
      open={openHarvest}
    >
      <DialogTitle sx={{ textAlign: 'center', m: 0, p: 2, bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor, fontSize: '2.5rem' }} id="customized-dialog-title">
        Harvest
      </DialogTitle>
      <IconButton
        aria-label="close"
        onClick={handleCloseHarvest}
        sx={{
          position: 'absolute',
          right: 8,
          top: 8,
          color: (theme) => theme.palette.grey[500],
        }}
      >
        <CloseIcon />
      </IconButton>
      <DialogContent dividers sx={{bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor, dissplay: 'flex', flexDirection: { xs: 'column', md: 'row' }, gap: 4}}>
      <Card sx={{width: '90vw',maxWidth: 500, minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none', '@media (min-width:1665px)': {
        width: '45%',
      } }}>
      <CardCover>
        <img
          src={harvestdecor}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
      <CardCover
        sx={{
          background:
            'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 100px), linear-gradient(to top, rgba(0,0,0,0.8), rgba(0,0,0,0) 200px)',
        }}
      />
      <CardContent sx={{ justifyContent: 'flex-end', p: 2 }}>
        <Typography level="title-lg" textColor="#fff" mb={1} sx={{ textShadow: '0 2px 4px rgba(0,0,0,0.5)' }}>
          Harvest
        </Typography>
        <Typography
          startDecorator={<LocationOnRoundedIcon sx={{ fontSize: '16px' }} />}
          textColor="neutral.300"
          fontSize="sm"
          // sx={{ alignItems: 'center' }}
        >
          Sophia Antipolis, France
        </Typography>
      </CardContent>
    </Card>
    <Box sx={{
      width: '100%',
      maxWidth: 800,
      marginTop: { xs: 2, lg: 0 },
      // Même logique pour le texte
      '@media (min-width:1665px)': {
        width: '45%',
      },
    }}>
        <Typography gutterBottom sx={{color: darkMode ? themes.dark.text : themes.light.textColor, marginTop:'2%'}}>
          {t('ABOUT_HARVEST_DESCRIPTION_1')}
        </Typography><br></br>
        <Typography gutterBottom sx={{color: darkMode ? themes.dark.text : themes.light.textColor}}>
          {t('ABOUT_HARVEST_DESCRIPTION_2')}
        </Typography><br></br>
        <Typography gutterBottom sx={{color: darkMode ? themes.dark.text : themes.light.textColor}}>
          {t('ABOUT_HARVEST_DESCRIPTION_3')}
        </Typography><br></br>
        <Typography gutterBottom sx={{color: DarkMode ? themes.dark.text : themes.light.textColor, marginBottom: '2%'}}>
        Ce projet m'a permis de développer mes compétences techniques en Java et Angular, ainsi que ma capacité à travailler avec des APIs externes.
        </Typography>
      </Box>
      </DialogContent>
    </BootstrapDialog>
    </Box>
    </Box>
    </Box>
  );
};

export default About;
